import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Interface: Structure","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/interfaces/Structure.md","filePath":"api/@jsprismarine/prismarine/interfaces/Structure.md"}`),a={name:`api/@jsprismarine/prismarine/interfaces/Structure.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / Structure</p><h1 id="interface-structure" tabindex="-1">Interface: Structure <a class="header-anchor" href="#interface-structure" aria-label="Permalink to “Interface: Structure”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/world/generators/structure/Structure.ts#L193" target="_blank" rel="noreferrer">packages/prismarine/src/world/generators/structure/Structure.ts:193</a></p><p>Something world generation builds that is larger than a chunk.</p><p>Chunks are generated in isolation and in no particular order, with no access to their neighbors - which is the whole difficulty. A structure gets around it by being a pure function of its origin: any chunk can work out on its own which structures reach it, plan each of them from scratch, and draw the slice it owns. No chunk needs to have been generated first, and generating one twice gives the same result.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/world/generators/structure/Structure.ts#L195" target="_blank" rel="noreferrer">packages/prismarine/src/world/generators/structure/Structure.ts:195</a></p><p>Used in logs and tests.</p><hr><h3 id="placement" tabindex="-1">placement <a class="header-anchor" href="#placement" aria-label="Permalink to “placement”">​</a></h3><blockquote><p><code>readonly</code> <strong>placement</strong>: <a href="./../classes/StructurePlacement.html"><code>StructurePlacement</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/world/generators/structure/Structure.ts#L198" target="_blank" rel="noreferrer">packages/prismarine/src/world/generators/structure/Structure.ts:198</a></p><p>How thinly this structure is spread across the world.</p><hr><h3 id="reach" tabindex="-1">reach <a class="header-anchor" href="#reach" aria-label="Permalink to “reach”">​</a></h3><blockquote><p><code>readonly</code> <strong>reach</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/world/generators/structure/Structure.ts#L207" target="_blank" rel="noreferrer">packages/prismarine/src/world/generators/structure/Structure.ts:207</a></p><p>How far the structure may reach from its origin, in blocks.</p><p>An over-estimate is merely wasteful - it makes nearby chunks plan a structure that turns out not to touch them. An under-estimate truncates the structure at a chunk border, so this is the one number here that has to be generous rather than accurate.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="plan" tabindex="-1">plan() <a class="header-anchor" href="#plan" aria-label="Permalink to “plan()”">​</a></h3><blockquote><p><strong>plan</strong>(<code>origin</code>, <code>random</code>, <code>terrain</code>): <a href="./StructurePlan.html"><code>StructurePlan</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/10b7a1361bf615d62b22ef5c463d07d785eed56a/packages/prismarine/src/world/generators/structure/Structure.ts#L214" target="_blank" rel="noreferrer">packages/prismarine/src/world/generators/structure/Structure.ts:214</a></p><p>Plans the structure at an origin, or refuses the site.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="origin" tabindex="-1">origin <a class="header-anchor" href="#origin" aria-label="Permalink to “origin”">​</a></h5><p><a href="./StructureOrigin.html"><code>StructureOrigin</code></a></p><h5 id="random" tabindex="-1">random <a class="header-anchor" href="#random" aria-label="Permalink to “random”">​</a></h5><p><code>ChunkRandom</code></p><h5 id="terrain" tabindex="-1">terrain <a class="header-anchor" href="#terrain" aria-label="Permalink to “terrain”">​</a></h5><p><a href="./TerrainSampler.html"><code>TerrainSampler</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./StructurePlan.html"><code>StructurePlan</code></a> | <code>null</code></p><p>Null when the terrain will not take it - underwater, too steep - which is the ordinary way a candidate origin comes to nothing.</p>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};